var e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:`用安全的「如果-就」規則自動化你的印表機。預設關閉；每條規則需自行啟用。`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`目前還沒有規則。在下方新增一條，準備好後再啟用。`}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:`規則引擎已開啟`}},off:{t:0,b:{t:2,i:[{t:3}],s:`規則引擎已關閉`}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:`開啟`}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:`關閉`}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:`必須同時開啟引擎與該條規則，規則才會執行。`}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:`當列印完成時`}},print_error:{t:0,b:{t:2,i:[{t:3}],s:`當印表機發生錯誤時`}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:`當加熱器溫度高於`}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:`當加熱器溫度低於`}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:`記錄一則通知`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`執行一條 G-code 指令`}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:`已啟用`}},arm:{t:0,b:{t:2,i:[{t:3}],s:`已停用`}},edit:{t:0,b:{t:2,i:[{t:3}],s:`編輯`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`刪除`}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:`刪除規則`}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:`規則名稱`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`例如：列印後關閉加熱器`}},trigger:{t:0,b:{t:2,i:[{t:3}],s:`如果（觸發條件）`}},action:{t:0,b:{t:2,i:[{t:3}],s:`就（動作）`}},heater:{t:0,b:{t:2,i:[{t:3}],s:`加熱器`}},value:{t:0,b:{t:2,i:[{t:3}],s:`溫度（°C）`}},message:{t:0,b:{t:2,i:[{t:3}],s:`訊息`}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`顯示於規則紀錄中`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`例如：TURN_OFF_HEATERS`}},save:{t:0,b:{t:2,i:[{t:3}],s:`儲存規則`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`取消`}},add:{t:0,b:{t:2,i:[{t:3}],s:`新增規則`}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:`近期活動`}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:`已通知`}},ran:{t:0,b:{t:2,i:[{t:3}],s:`已執行 G-code`}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:`已略過（印表機忙碌中）`}},error:{t:0,b:{t:2,i:[{t:3}],s:`錯誤`}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`指南`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`規則引擎指南`}},close:{t:0,b:{t:2,i:[{t:3}],s:`關閉`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`什麼是規則引擎？`}},body:{t:0,b:{t:2,i:[{t:3}],s:`它會監看印表機，並在符合你設定的條件時執行一個動作 - 例如在列印完成時記錄一則備註，或關閉加熱器。每條規則都是「如果（觸發條件），就（動作）」。`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`它如何保持安全`}},body:{t:0,b:{t:2,i:[{t:3}],s:`引擎預設關閉，而且每條規則都必須個別啟用，因此不會有任何意外執行。當條件首次成立時，規則只會觸發一次。G-code 動作只會在印表機閒置時執行 - 列印期間會被拒絕 - 而且每個結果都會被記錄。`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`詞彙表`}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:`觸發條件`}},def:{t:0,b:{t:2,i:[{t:3}],s:`啟動規則的條件，例如列印完成或加熱器跨越某個溫度。`}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:`動作`}},def:{t:0,b:{t:2,i:[{t:3}],s:`規則觸發時所執行的事：記錄一則通知，或執行一條 G-code 指令（僅在閒置時）。`}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:`已啟用`}},def:{t:0,b:{t:2,i:[{t:3}],s:`已開啟的規則。已停用的規則會被保留，但永遠不會觸發。`}}}}}}};export{e as default};